 db.exec(`CREATE TABLE IF NOT EXISTS department_teachers(id INTEGER PRIMARY KEY,name TEXT NOT NULL,grade TEXT NOT NULL DEFAULT '',specialty TEXT NOT NULL DEFAULT '',levels_json TEXT NOT NULL DEFAULT '[]',tracks_json TEXT NOT NULL DEFAULT '[]',status TEXT NOT NULL DEFAULT 'active',created_at TEXT NOT NULL,updated_at TEXT NOT NULL);CREATE TABLE IF NOT EXISTS department_teacher_history(id INTEGER PRIMARY KEY,teacher_id INTEGER NOT NULL,actor_id INTEGER NOT NULL,previous_json TEXT NOT NULL,changed_at TEXT NOT NULL);CREATE INDEX IF NOT EXISTS idx_department_teachers_name ON department_teachers(name);`);
