init();
function audit(actor,action,entity,id,details={}){run('INSERT INTO audit(actor_id,action,entity,entity_id,details,created_at) VALUES (?,?,?,?,?,?)',actor,action,entity,id,JSON.stringify(details),now())}
function roleRows(uid){return all("SELECT r.id,r.name,r.permissions,ur.scope,r.scope_type,r.scope_value FROM user_roles ur JOIN roles r ON r.id=ur.role_id JOIN users holder ON holder.id=ur.user_id WHERE ur.user_id=? AND r.suspended=0 AND (r.scope_type<>'level' OR holder.level=r.scope_value) AND (ur.expires_at IS NULL OR ur.expires_at>?)",uid,now())}
function roleNames(uid){return new Set(roleRows(uid).map(x=>x.name))}
function perms(uid){return new Set(roleRows(uid).flatMap(x=>JSON.parse(x.permissions)))}
function has(u,p){return !!u&&perms(u.id).has(p)}
function requireP(u,p){if(!has(u,p))fail('Accès refusé : autorisation insuffisante.',403)}
function publicUser(u){return {id:u.id,name:u.name,email:u.email,phone:u.phone,identifier:u.identifier,status:u.status,level:u.level,track:u.track,year_id:u.year_id,created_at:u.created_at,roles:roleRows(u.id).map(x=>({name:x.name,scope:x.scope})),permissions:[...perms(u.id)].sort()}}
function audienceOk(u,a,t){const r=roleNames(u.id);return a==='all'||a==='students'&&r.has('etudiant')||a==='teachers'&&r.has('enseignant')||a==='level'&&u.level===t||a==='track'&&u.track===t||a==='role'&&r.has(t)||a==='licence'&&u.level?.startsWith('Licence')||a==='master'&&u.level?.startsWith('Master')||a==='doctorat'&&u.level==='Doctorat'}
function trackCycle(level){return String(level||'').startsWith('Licence')?'Licence':String(level||'').startsWith('Master')?'Master':String(level||'')==='Doctorat'?'Doctorat':''}
function checkTrack(name,level){if(!name)return;const row=one('SELECT * FROM tracks WHERE name=? AND status=?',name,'active');if(!row||!JSON.parse(row.levels_json).includes(trackCycle(level)))fail('Parcours inactif ou indisponible pour ce niveau.',400)}
function trackFields(input,current={}){const name=txt(input.name??current.name??'','Parcours',100),description=txt(input.description??current.description??'','Description',500,false),cycles=input.levels??JSON.parse(current.levels_json||'["Licence","Master","Doctorat"]'),teachers=input.teacher_ids??JSON.parse(current.teacher_ids_json||'[]'),status=input.status??current.status??'active';if(!Array.isArray(cycles)||!cycles.length||cycles.some(x=>!['Licence','Master','Doctorat'].includes(x)))fail('Niveaux invalides.');if(!Array.isArray(teachers)||teachers.length>40||teachers.some(x=>!Number.isSafeInteger(Number(x))||!one("SELECT id FROM users WHERE id=? AND status='active'",x)||!roleNames(Number(x)).has('enseignant')))fail('Enseignants responsables invalides.');if(!['active','suspended','archived'].includes(status))fail('Statut du parcours invalide.');return {name,description,levels_json:JSON.stringify([...new Set(cycles)]),teacher_ids_json:JSON.stringify([...new Set(teachers.map(Number))]),status}}
function checkAudience(a,t){if(!['all','students','teachers','level','track','role','licence','master','doctorat'].includes(a))fail('Public cible invalide.');if(['level','track','role'].includes(a)){if(!t)fail('Précisez le public ciblé.');const table={level:'levels',track:'tracks',role:'roles'}[a];if(!one(`SELECT 1 FROM ${table} WHERE name=?`,t))fail('Cible inconnue.')}}
function checkScope(u,a,t,resource){if(has(u,'announcements.publish')||has(u,'documents.manage')||has(u,'users.manage'))return;const r=roleNames(u.id);if(r.has('secretariat')&&['announcement','event'].includes(resource))return;if((r.has('responsable_niveau')||r.has('delegue')||has(u,'delegation.relay'))&&a==='level'&&t&&t===u.level)return;if(r.has('responsable_parcours')&&a==='track'&&t&&t===u.track)return;if(r.has('ancien')&&resource==='announcement')return;if(r.has('enseignant')){if(a==='teachers')return;if(a==='level'&&one('SELECT 1 FROM courses WHERE teacher_id=? AND level=?',u.id,t))return}fail('Public hors de votre périmètre.',403)}
function notify(uid,title,body,link='',entityType=null,entityId=null){const id=run('INSERT INTO notifications(user_id,title,body,link,created_at,entity_type,entity_id) VALUES (?,?,?,?,?,?,?)',uid,title,body,link,now(),entityType,entityId).lastInsertRowid;push.queue(id,uid);return id}
function notifyAudience(a,t,title,body,link){for(const u of all("SELECT * FROM users WHERE status='active'"))if(audienceOk(u,a,t))notify(u.id,title,body,link)}
