function wrap(fn){return (req,res,next)=>{try{if(!req.user)fail('Veuillez vous connecter.',401);let result;if(['POST','PATCH','DELETE'].includes(req.method)){result=db.transaction(()=>fn(req,res))();setImmediate(()=>push.flush().catch(e=>console.warn('Push:',e.message)))}else result=fn(req,res);if(result!==undefined&&!res.headersSent)res.json(result)}catch(e){next(e)}}}
function publicRoute(fn){return (req,res,next)=>{try{const out=fn(req,res);if(out&&typeof out.then==='function')out.then(x=>{if(x!==undefined&&!res.headersSent)res.json(x)}).catch(next);else if(out!==undefined&&!res.headersSent)res.json(out)}catch(e){next(e)}}}
function route(method,p,fn){app[method](p,wrap(fn))}
