function canSeeNotification(n){if(!n.entity_type)return true;if(n.entity_type==='result'){const r=one('SELECT * FROM results WHERE id=?',n.entity_id);return !!r&&r.student_id===n.user_id&&r.status==='published'}try{const x=sharing.info(n.entity_type,n.entity_id),u=one('SELECT * FROM users WHERE id=?',n.user_id);return !!u&&x.status==='published'&&sharing.canAccess(u,n.entity_type,x)}catch{return false}}
