route('post','/api/documents/upload',req=>{
 const u=req.user,q=req.query;if(!has(u,'documents.manage')&&!has(u,'documents.create'))fail('Accès refusé.',403);const content=req.body;if(!Buffer.isBuffer(content)||!content.length||content.length>controls.policy().document_max_bytes)fail('Fichier requis ou taille supérieure à la limite configurée.',413);
 const mime=String(req.headers['content-type']||'').split(';')[0],filename=path.basename(String(q.filename||''));if(!MIMES[mime]||!filename.toLowerCase().endsWith(MIMES[mime]))fail('Type de fichier non autorisé.');
 let supplied;if(q.targets!==undefined){try{supplied=JSON.parse(String(q.targets))}catch{fail('Destinataires invalides.')}}
 const targets=sharing.parseTargets(u,supplied,String(q.audience||'all'),String(q.target||''));const first=targets[0];
 if(mime==='application/pdf'&&!content.subarray(0,5).equals(Buffer.from('%PDF-')))fail('PDF invalide.');
 if(mime==='image/png'&&!content.subarray(0,8).equals(Buffer.from([137,80,78,71,13,10,26,10])))fail('PNG invalide.');
 if(mime==='image/jpeg'&&!content.subarray(0,2).equals(Buffer.from([255,216])))fail('JPEG invalide.');
 if((mime.includes('wordprocessingml')||mime.includes('spreadsheetml'))&&!content.subarray(0,2).equals(Buffer.from('PK')))fail('Document Office invalide.');
 const storage=crypto.randomBytes(24).toString('hex')+MIMES[mime];if(db.kind==='postgres')run('INSERT INTO file_blobs(storage_name,data,mime,size,created_at) VALUES (?,?,?,?,?)',storage,content,mime,content.length,now());else fs.writeFileSync(path.join(UPLOADS,storage),content,{flag:'wx'});
 try{const title=txt(String(q.title||''),'Titre',160),id=run('INSERT INTO documents(title,category,author,document_year,level,audience,target,filename,storage_name,mime,size,uploaded_by,created_at,status) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)',title,txt(String(q.category||'Ressource'),'Catégorie',70),txt(String(q.author||''),'Auteur',120,false),txt(String(q.document_year||''),'Année',10,false),txt(String(q.level||''),'Niveau',80,false),first.type,first.id,filename,storage,mime,content.length,u.id,now(),'published').lastInsertRowid;sharing.save('document',id,u.id,targets,q.requires_ack==='true');sharing.publish('document',id,u.id,title);audit(u.id,'document.upload','document',id,{filename,size:content.length});return {id}}catch(e){if(db.kind!=='postgres')fs.rmSync(path.join(UPLOADS,storage),{force:true});throw e}
});
